SELECT count(*) 
FROM (
  SELECT a.*, ROWNUM rn 
  FROM (
    -- 실제 데이터 쿼리
    SELECT *
    FROM product

      del_status = 0

        AND product_status = #{product_status}


        AND LOWER(product_name) LIKE LOWER('%' || #{product_name} || '%')


        AND TRUNC(in_date) >= #{startDate}


        AND TRUNC(in_date) <= #{endDate}


    ORDER BY product_no
  ) a
)

SELECT * 
FROM (
  SELECT a.*, ROWNUM rn 
  FROM (
    -- 실제 데이터 쿼리
    SELECT *
    FROM product

      del_status = 0

        AND product_status = #{product_status}


        AND LOWER(product_name) LIKE LOWER('%' || #{product_name} || '%')


        AND TRUNC(in_date) >= #{startDate}


        AND TRUNC(in_date) <= #{endDate}


    ORDER BY product_no desc
  ) a
  WHERE ROWNUM <= #{end}   
)
WHERE rn >= #{start}

